// ===== Router: يفهم رسالة اليوزر (سورة + نطاق) ويدير حالة الجلسة =====
const SURAHS = [[1, "الفاتحة", 7], [2, "البقرة", 286], [3, "آل عمران", 200], [4, "النساء", 176], [5, "المائدة", 120], [6, "الأنعام", 165], [7, "الأعراف", 206], [8, "الأنفال", 75], [9, "التوبة", 129], [10, "يونس", 109], [11, "هود", 123], [12, "يوسف", 111], [13, "الرعد", 43], [14, "إبراهيم", 52], [15, "الحجر", 99], [16, "النحل", 128], [17, "الإسراء", 111], [18, "الكهف", 110], [19, "مريم", 98], [20, "طه", 135], [21, "الأنبياء", 112], [22, "الحج", 78], [23, "المؤمنون", 118], [24, "النور", 64], [25, "الفرقان", 77], [26, "الشعراء", 227], [27, "النمل", 93], [28, "القصص", 88], [29, "العنكبوت", 69], [30, "الروم", 60], [31, "لقمان", 34], [32, "السجدة", 30], [33, "الأحزاب", 73], [34, "سبأ", 54], [35, "فاطر", 45], [36, "يس", 83], [37, "الصافات", 182], [38, "ص", 88], [39, "الزمر", 75], [40, "غافر", 85], [41, "فصلت", 54], [42, "الشورى", 53], [43, "الزخرف", 89], [44, "الدخان", 59], [45, "الجاثية", 37], [46, "الأحقاف", 35], [47, "محمد", 38], [48, "الفتح", 29], [49, "الحجرات", 18], [50, "ق", 45], [51, "الذاريات", 60], [52, "الطور", 49], [53, "النجم", 62], [54, "القمر", 55], [55, "الرحمن", 78], [56, "الواقعة", 96], [57, "الحديد", 29], [58, "المجادلة", 22], [59, "الحشر", 24], [60, "الممتحنة", 13], [61, "الصف", 14], [62, "الجمعة", 11], [63, "المنافقون", 11], [64, "التغابن", 18], [65, "الطلاق", 12], [66, "التحريم", 12], [67, "الملك", 30], [68, "القلم", 52], [69, "الحاقة", 52], [70, "المعارج", 44], [71, "نوح", 28], [72, "الجن", 28], [73, "المزمل", 20], [74, "المدثر", 56], [75, "القيامة", 40], [76, "الإنسان", 31], [77, "المرسلات", 50], [78, "النبأ", 40], [79, "النازعات", 46], [80, "عبس", 42], [81, "التكوير", 29], [82, "الانفطار", 19], [83, "المطففين", 36], [84, "الانشقاق", 25], [85, "البروج", 22], [86, "الطارق", 17], [87, "الأعلى", 19], [88, "الغاشية", 26], [89, "الفجر", 30], [90, "البلد", 20], [91, "الشمس", 15], [92, "الليل", 21], [93, "الضحى", 11], [94, "الشرح", 8], [95, "التين", 8], [96, "العلق", 19], [97, "القدر", 5], [98, "البينة", 8], [99, "الزلزلة", 8], [100, "العاديات", 11], [101, "القارعة", 11], [102, "التكاثر", 8], [103, "العصر", 3], [104, "الهمزة", 9], [105, "الفيل", 5], [106, "قريش", 4], [107, "الماعون", 7], [108, "الكوثر", 3], [109, "الكافرون", 6], [110, "النصر", 3], [111, "المسد", 5], [112, "الإخلاص", 4], [113, "الفلق", 5], [114, "الناس", 6]]; // [رقم, اسم, عدد الآيات]

const msg = $input.first().json.message || {};
const chatId = msg.chat && msg.chat.id;

const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const s = sd.sessions[chatId] = sd.sessions[chatId] || { stage: 'idle', surah: null, from: null, to: null, ayah: null };

const toEn = (t) => String(t || '')
  .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
  .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
const norm = (t) => String(t || '').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g, '')
  .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').trim().toLowerCase();
const keyOf = (t) => norm(t).replace(/ؤ/g, 'و').replace(/ئ/g, 'ي').replace(/ء/g, '')
  .replace(/[^\u0621-\u064A]/g, '').replace(/^ال/, '');
const KEYS = SURAHS.map(x => keyOf(x[1]));

const out = (o) => [{ json: Object.assign({ chatId }, o) }];
const reply = (text) => out({ action: 'reply', text });

const ask = () => {
  const info = SURAHS[s.surah - 1];
  const size = s.to - s.from + 1;
  let n = s.from + Math.floor(Math.random() * size);
  if (size > 1) { let g = 0; while (n === s.ayah && g++ < 10) n = s.from + Math.floor(Math.random() * size); }
  s.ayah = n;
  s.stage = 'awaiting_voice';
  return out({ action: 'ask', surah: s.surah, surahName: info[1], total: info[2], ayah: n });
};

const HELP = '🕌 <b>رفيق القرآن</b>\n\n' +
  '1️⃣ ابعتلي السورة والنطاق، مثال: <b>البقرة 1 10</b> أو <b>الكهف 1 10</b> أو <b>18 1 10</b> (رقم السورة ثم من ثم إلى)\n' +
  '   ولو كتبت اسم السورة بس هسألك على النطاق، أو اكتب <b>كاملة</b> لاختبارك في السورة كلها\n' +
  '2️⃣ هختار آية عشوائية من النطاق وأديك أول 3 كلمات منها\n' +
  '3️⃣ ابعتلي <b>رسالة صوتية</b> بتكمل فيها الآية والآية اللي بعدها\n' +
  '4️⃣ هراجع تلاوتك بالتشكيل وأقولك صح ولا غلط، وبعدها تقرر تكمل ولا لأ\n\n' +
  'الأوامر:\n/start - البداية\n/help - المساعدة\n/stop - إنهاء الجلسة\n' +
  'ولو عايز نفس السورة والنطاق القديم اكتب: <b>نفس النطاق</b>';

const voice = msg.voice || msg.audio;
const text = (msg.text || '').trim();

// ---------- رسالة صوتية ----------
if (voice && voice.file_id) {
  if (s.stage === 'awaiting_voice' && s.ayah && s.surah) {
    const info = SURAHS[s.surah - 1];
    return out({ action: 'evaluate', surah: s.surah, surahName: info[1], total: info[2], ayah: s.ayah, fileId: voice.file_id });
  }
  return reply('محتاج الأول تحدد السورة والنطاق 📖\nابعتلي مثلاً: <b>البقرة 1 10</b> وبعدها هسألك وتسمّع بصوتك.');
}

// ---------- رسالة غير نصية ----------
if (!text) return reply('ابعتلي السورة والنطاق (مثال: <b>البقرة 1 10</b>) أو رسالة صوتية بالتسميع 🎙️');

const t = norm(text);

// ---------- أوامر ----------
if (t.startsWith('/start') || t.startsWith('/help')) {
  s.stage = 'idle';
  return reply(HELP);
}
if (t.startsWith('/stop')) {
  s.stage = 'idle'; s.ayah = null;
  return reply('تم إنهاء الجلسة 🌙 تقبّل الله منك، ونتقابل بإذن الله في المراجعة الجاية.');
}

// ---------- نفس النطاق ----------
if (t.includes('نفس') && s.surah && s.from) return ask();

// ---------- تحليل السورة والنطاق ----------
const nums = (toEn(text).match(/\d+/g) || []).map(n => parseInt(n, 10));
const FILL = new Set(['سوره', 'من', 'الي', 'ايه', 'ايات', 'في', 'عايز', 'عاوز', 'عايزه', 'عاوزه', 'اختبار', 'اختبرني', 'كامله', 'كامل', 'كل', 'ال', 'ورقم', 'رقم']);
const letters = norm(toEn(text).replace(/\d+/g, ' ')).split(/\s+/).filter(w => w && !FILL.has(w));
const cand = keyOf(letters.join(''));
let idx = cand ? KEYS.indexOf(cand) : -1;
if (idx < 0 && cand.length >= 3) {
  const m = KEYS.map((k, i) => (k.startsWith(cand) ? i : -1)).filter(i => i >= 0);
  if (m.length === 1) idx = m[0];
}
const whole = /(^|\s)(كامل|كامله|كل)(\s|$)/.test(t);

let surah = null;
let range = [];
if (idx >= 0) { surah = idx + 1; range = nums.slice(0, 2); }
else if (nums.length >= 3) { surah = nums[0]; range = nums.slice(1, 3); }
else if (nums.length >= 1 && s.surah && s.stage !== 'idle') { surah = s.surah; range = nums.slice(0, 2); }
else if (nums.length >= 1) {
  return reply('اكتب اسم السورة كمان 📖 مثال: <b>البقرة 1 10</b>');
}
else if (whole && s.surah && s.stage !== 'idle') { surah = s.surah; }

if (surah !== null) {
  if (surah < 1 || surah > 114) return reply('⚠️ رقم السورة لازم يكون بين <b>1</b> و <b>114</b>.');
  const info = SURAHS[surah - 1];
  const count = info[2];
  let a, b;
  if (range.length === 0) {
    if (whole) { a = 1; b = count; }
    else {
      s.surah = surah; s.stage = 'awaiting_range'; s.ayah = null;
      return reply('تمام ✅ سورة <b>' + info[1] + '</b> (' + count + ' آية).\nابعتلي النطاق، مثال: <b>1 ' + Math.min(10, count) + '</b>\nأو اكتب <b>كاملة</b> لاختبارك في السورة كلها.');
    }
  } else {
    a = range[0]; b = range.length >= 2 ? range[1] : range[0];
    if (a > b) { const x = a; a = b; b = x; }
  }
  if (a < 1 || b > count) {
    return reply('⚠️ سورة <b>' + info[1] + '</b> فيها <b>' + count + '</b> آية بس. ابعت نطاق صحيح.');
  }
  s.surah = surah; s.from = a; s.to = b;
  return ask();
}

// ---------- الاستمرار أو التوقف ----------
if (s.stage === 'awaiting_continue') {
  if (/^(نعم|ايوه|ايوا|اه|يلا|كمل|اكمل|كمان|تمام|اوك|ok|yes|y)/.test(t)) return ask();
  if (/^(لا|خلاص|كفايه|كفي|توقف|بس|no|stop|n)/.test(t)) {
    s.stage = 'idle'; s.ayah = null;
    return reply('تقبّل الله منك 🌙 هنتقابل بإذن الله في تذكير الغد الساعة 9. ولو حبيت تكمل ابعتلي سورة ونطاق جديد في أي وقت.');
  }
  return reply('رد بـ <b>نعم</b> لو عايز آية عشوائية تانية، أو <b>لا</b> لو كفاية كده. أو ابعت سورة ونطاق جديد.');
}

if (s.stage === 'awaiting_voice') {
  return reply('ابعتلي تسجيلك الصوتي 🎙️ لإكمال الآية، أو ابعت سورة ونطاق جديد لو عايز تغيّر.');
}
if (s.stage === 'awaiting_range') {
  return reply('ابعتلي النطاق، مثال: <b>1 10</b> أو اكتب <b>كاملة</b>.');
}

return reply('ابعتلي السورة والنطاق اللي عايز تتختبر فيه، مثال: <b>البقرة 1 10</b>\nأو اكتب /help للمساعدة.');

// ===== Process: يجهز السؤال أو بيانات التقييم من صفوف السورة المختارة =====
const COL_AYAH = 'رقم الآية';
const COL_TEXT = 'النص الكامل بالتشكيل';

const r = $('Router').first().json;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toEn = (t) => String(t == null ? '' : t)
  .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
  .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
const fail = (text) => [{ json: { action: 'reply', chatId: r.chatId, text } }];

const rows = $input.all().map(i => i.json).filter(x => x && Object.keys(x).length);
if (!rows.length) return fail('⚠️ ماقدرتش ألاقي آيات سورة ' + r.surahName + ' في الشيت. اتأكد إن الشيت فيه عمود "رقم السورة" وإن الـ node بيقرا الشيت الصح.');
if (rows[0][COL_AYAH] === undefined || rows[0][COL_TEXT] === undefined) {
  return fail('⚠️ أسماء الأعمدة في الشيت مختلفة. الموجود: ' + Object.keys(rows[0]).join(' | ') + '\nلازم تكون: ' + COL_AYAH + ' | ' + COL_TEXT);
}

// نشيل علامات الوقف والحزب والسجدة (مش بتتنطق) ونظبط المسافات
const clean = (t) => String(t == null ? '' : t)
  .replace(/[\u06D6-\u06DC\u06DE\u06E9۝﴿﴾]/g, '').replace(/[0-9٠-٩۰-۹]+/g, '').replace(/\s+/g, ' ').trim();
const getAyah = (n) => {
  const row = rows.find(x => parseInt(toEn(x[COL_AYAH]), 10) === n);
  return row ? clean(row[COL_TEXT]) : null;
};

const n = r.ayah;
const a = getAyah(n);
if (!a) return fail('⚠️ ماقدرتش ألاقي الآية رقم ' + n + ' من سورة ' + r.surahName + ' في الشيت.');
const words = a.split(' ');
const nextText = n < r.total ? getAyah(n + 1) : null;

// ---------- سؤال ----------
if (r.action === 'ask') {
  let text;
  if (words.length <= 3) {
    text = '📖 سورة <b>' + esc(r.surahName) + '</b> - الآية <b>' + n + '</b>:\n<b>' + esc(a) + '</b>\n\n' +
      (nextText ? 'أرسل بصوتك الآية التي تليها (رقم ' + (n + 1) + ') 🎙️' : 'أعدها بصوتك 🎙️');
  } else {
    text = '📖 سورة <b>' + esc(r.surahName) + '</b> - الآية <b>' + n + '</b>\nأكمل بعد: <b>' + esc(words.slice(0, 3).join(' ')) + '</b> ...\n' +
      (nextText ? 'ثم الآية التي تليها 🎙️\n' : '') + 'أرسل تسجيلك الصوتي الآن';
  }
  return [{ json: { action: 'ask', chatId: r.chatId, text } }];
}

// ---------- تقييم ----------
let parts = [];   // [{label, text}]
let shownInfo = '';
if (words.length <= 3) {
  if (nextText) parts.push({ label: 'الآية ' + (n + 1), text: nextText });
  shownInfo = 'أُعطي القارئ الآية ' + n + ' كاملة (' + a + ') وطُلب منه تلاوة الآية التي تليها فقط.';
} else {
  parts.push({ label: 'تكملة الآية ' + n, text: words.slice(3).join(' ') });
  if (nextText) parts.push({ label: 'الآية ' + (n + 1), text: nextText });
  shownInfo = 'أُعطي القارئ أول ثلاث كلمات فقط (' + words.slice(0, 3).join(' ') + ') وطُلب منه إكمال الآية ثم تلاوة الآية التي تليها. عدم نطقه للكلمات الثلاث الأولى ليس خطأً.';
}
if (!parts.length) return fail('⚠️ مفيش نص للتقييم لهذه الآية.');
const expected = parts.map(p => p.label + ': ' + p.text).join('\n');
const expectedDisplay = parts.map(p => '<b>' + esc(p.label) + ':</b>\n' + esc(p.text)).join('\n\n');

const prompt = 'أنت مصحح تلاوة قرآنية متقن وصارم. استمع إلى التسجيل الصوتي المرفق وقارن ما نطقه القارئ فعلياً بالنص الصحيح التالي كلمة بكلمة.\n\n' +
  'النص الصحيح (من سورة ' + r.surahName + '):\n' + expected + '\n\n' +
  'سياق: ' + shownInfo + '\n\n' +
  'القواعد:\n' +
  '- قد يكون القارئ أخطأ، فلا تفترض أنه قرأ النص الصحيح ولا تصحح له تلقائياً؛ احكم على ما سمعته فعلاً.\n' +
  '- الأخطاء المعتبرة: كلمة ناقصة، كلمة زائدة، كلمة مبدلة بغيرها، تقديم أو تأخير كلمات، وخطأ في حركات الحروف (فتحة/ضمة/كسرة/سكون/تنوين/شدة) خاصة ما يغيّر الإعراب أو المعنى.\n' +
  '- لا تعتبر أخطاءً: دقائق التجويد (مقدار المد، الغنة، الإخفاء، الإدغام، القلقلة)، جودة الصوت، التوقف والتنفس، وسكون آخر الكلمة عند الوقف.\n' +
  '- إذا كان التسجيل غير واضح أو صامتاً أو لا يحتوي تلاوة، اجعل unclear = true.\n\n' +
  'أرجع JSON فقط، بدون أي نص آخر وبدون علامات ```، بهذا الشكل بالضبط:\n' +
  '{"correct": true, "unclear": false, "errors": []}\n' +
  'حيث errors قائمة نصوص عربية قصيرة، كل نص يصف خطأ واحداً بدقة، مثال: "نطقتَ (كلمة) بالفتح والصحيح بالضم".';

return [{ json: { action: 'evaluate', chatId: r.chatId, ayah: n, fileId: r.fileId, prompt, expectedDisplay } }];

// ===== Finalize: يقرأ رد Gemini ويبني رسالة النتيجة + يحدّث الحالة =====
const p = $('Process').first().json;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sd = $getWorkflowStaticData('global');
const s = (sd.sessions || {})[p.chatId];

const j = $input.first().json || {};
let raw = '';
if (j.content && Array.isArray(j.content.parts)) raw = j.content.parts.map(x => x.text || '').join('');
else if (j.candidates && j.candidates[0] && j.candidates[0].content) raw = (j.candidates[0].content.parts || []).map(x => x.text || '').join('');
else if (typeof j.text === 'string') raw = j.text;
raw = String(raw).replace(/```json|```/g, '').trim();

let v = null;
try { const m = raw.match(/\{[\s\S]*\}/); if (m) v = JSON.parse(m[0]); } catch (e) { v = null; }

const send = (text) => [{ json: { chatId: p.chatId, text } }];

if (!v || v.unclear) {
  if (s) s.stage = 'awaiting_voice';
  return send('🎧 ماقدرتش أسمع التلاوة بوضوح. ابعت التسجيل تاني من فضلك (في مكان هادي وبصوت واضح).');
}

if (s) s.stage = 'awaiting_continue';
const errors = Array.isArray(v.errors) ? v.errors.filter(Boolean) : [];
const ask = '\n\nتحب أختبرك بآية عشوائية تانية من نفس النطاق؟ (<b>نعم</b> / <b>لا</b>)\nأو ابعت نطاق جديد.';

if (v.correct === true && errors.length === 0) {
  return send('أحسنت ✅ تلاوة صحيحة ومتقنة، بارك الله فيك 🌟' + ask);
}

let text = '❌ <b>فيه ملاحظات على التلاوة:</b>\n' + errors.map(e => '• ' + esc(e)).join('\n');
if (!errors.length) text += '\n• في اختلاف عن النص الصحيح';
text += '\n\n📖 <b>الصحيح كاملاً:</b>\n\n' + p.expectedDisplay + ask;
return send(text);
